--- raiden_victory_objdump.lua - name every sprite on screen during Raiden's
--- victory stance.
---
--- Report: "little sprites by his armpits" during the pose, source unknown.
--- This dumps the whole display list at several points in the stance with each
--- object's art resolved back to its source label via tools/sag_labels.txt
--- (generated by tools/gen_sag_labels.py), plus its screen position and size,
--- so an unexplained sprite can be named instead of guessed at.
---
--- Env: RDOD_LOG, RDOD_DUMPS (comma-separated rel frames, default the pose)

local ROOT = "C:/Users/you/Workplace/mk2-main"

local LOG_PATH = os.getenv("RDOD_LOG") or (ROOT .. "/tools/raiden_victory_objdump.log")
local DUMPS = {}
for f in (os.getenv("RDOD_DUMPS") or "0,20,45,60,80,100,140,180,240"):gmatch("[^,]+") do
    DUMPS[#DUMPS + 1] = tonumber(f)
end
local LAST_DUMP = DUMPS[#DUMPS]

local logfh = io.open(LOG_PATH, "w")
local frame = 0
local raw_print = print
print = function(...)
    local parts = {}
    for i = 1, select("#", ...) do parts[#parts + 1] = tostring(select(i, ...)) end
    local line = table.concat(parts, "\t")
    raw_print(line)
    if logfh then logfh:write(line, "\n"); logfh:flush() end
end
local function log(fmt, ...)
    print("[rdod] " .. (select("#", ...) > 0 and string.format(fmt, ...) or tostring(fmt)))
end

local symbols = {}
do
    local fh = io.open(ROOT .. "/src/mk2.map", "r")
    if fh then
        for line in fh:lines() do
            for addr, name in line:gmatch("(%x%x%x%x%x%x%x%x)%s+([%w_%.]+)") do
                symbols[name] = tonumber(addr, 16)
            end
        end
        fh:close()
    end
end
local function sym(n)
    if symbols[n] == nil then log("WARN missing symbol %s", n) end
    return symbols[n] or 0
end

local sag_label = {}
do
    local n = 0
    local fh = io.open(ROOT .. "/tools/sag_labels.txt", "r")
    if fh then
        for line in fh:lines() do
            local sag, label = line:match("^(%x+)\t([^\t]+)\t")
            if sag then sag_label[tonumber(sag, 16)] = label; n = n + 1 end
        end
        fh:close()
    end
    log("loaded %d SAG labels", n)
end

local A = {
    gstate = sym("gstate"), winner_status = sym("winner_status"),
    p1_char = sym("p1_char"), p2_char = sym("p2_char"),
    p1_state = sym("p1_state"), p2_state = sym("p2_state"),
    p1_obj = sym("p1_obj"), p2_obj = sym("p2_obj"),
    p1_bar = sym("p1_bar"), p2_bar = sym("p2_bar"),
    curback = sym("curback"),
    objlst = sym("objlst"), objlst2 = sym("objlst2"), objlst3 = sym("objlst3"),
    worldtlx = sym("worldtlx"), worldtly = sym("worldtly"),
}
local O = { next = 0x000, oslink = 0x020, oxval = 0x080, oxpos = 0x090,
            oyval = 0x0a0, oypos = 0x0b0, ozval = 0x0c0, oflags = 0x0f0,
            osag = 0x100, osizex = 0x120, osizey = 0x130, opal = 0x140,
            oimg = 0x1a0, oid = 0x1c0, oshape = 0x1d0, ochar = 0x1f0 }

local GS_PSEL, GS_FIGHTING = 4, 2
local FT_RAIDEN, FT_JAX = 7, 11
local STAGE_ID = 5

local cpu, space, fields = nil, nil, {}
local last_gstate = -1
local charsel_frame, fighting_frame = 0, 0
local p1_confirm_start = 0
local killed_frame, win_frame = 0, 0
local finished = false
local snap_index = 0
local blanked_sag = nil

local function r16(a) return space:read_u16(a) end
local function r32(a) return space:read_u32(a) end
local function w16(a, v) space:write_u16(a, v & 0xffff) end
local function s16(v) return v >= 0x8000 and v - 0x10000 or v end

local function cache_fields()
    local wanted = { ["Coin 1"] = true, ["Coin 2"] = true, ["2 Players Start"] = true,
                     ["P1 High Punch"] = true, ["P2 High Punch"] = true }
    for _, port in pairs(manager.machine.ioport.ports) do
        for _, field in pairs(port.fields) do
            if wanted[field.name] then fields[field.name] = field end
        end
    end
    for name in pairs(wanted) do
        if not fields[name] then log("input %s MISSING", name); return false end
    end
    return true
end

local function main_screen()
    local ok, s = pcall(function() return manager.machine.screens[":screen"] end)
    if ok and s then return s end
    ok, s = pcall(function() return manager.machine.screens:at(1) end)
    return ok and s or nil
end

local function snap(label)
    local s = main_screen()
    local ok = false
    if s then ok = pcall(function() s:snapshot() end) end
    log("SNAP idx=%04d frame=%d label=%s ok=%s", snap_index, frame, label, tostring(ok))
    snap_index = snap_index + 1
end

local function dump_objects(tag)
    local raiden = r32(A.p1_obj)
    local rx = raiden ~= 0 and s16(r16(raiden + O.oxpos)) or 0
    local ry = raiden ~= 0 and s16(r16(raiden + O.oypos)) or 0
    log("---- objdump %s frame=%d gs=%d ws=%d raiden_obj=0x%08x at (%d,%d) worldtlx=%d ----",
        tag, frame, r16(A.gstate), r16(A.winner_status), raiden, rx, ry,
        A.worldtlx ~= 0 and s16(r16(A.worldtlx)) or -1)
    for li, list in ipairs({ A.objlst, A.objlst2, A.objlst3 }) do
        if list ~= 0 then
            local obj, guard, seen = r32(list), 0, {}
            while obj ~= 0 and guard < 400 do
                if seen[obj] then log("  list%d LOOP at 0x%08x", li, obj); break end
                seen[obj] = true
                local sag = r32(obj + O.osag)
                local img = r32(obj + O.oimg)
                local isag = img ~= 0 and r32(img) or 0
                local label = sag_label[sag] or sag_label[sag & 0x00ffffff]
                              or sag_label[isag] or sag_label[isag & 0x00ffffff] or "?"
                local x, y = s16(r16(obj + O.oxpos)), s16(r16(obj + O.oypos))
                log("  list%d obj=0x%08x %-16s xy=(%4d,%4d) rel=(%4d,%4d) size=%dx%d sag=0x%08x isag=0x%08x pal=0x%04x flags=0x%04x z=0x%08x id=0x%04x char=%d shape=0x%08x",
                    li, obj, label, x, y, x - rx, y - ry,
                    r16(obj + O.osizex), r16(obj + O.osizey),
                    sag, isag, r16(obj + O.opal), r16(obj + O.oflags),
                    r32(obj + O.ozval), r16(obj + O.oid), r16(obj + O.ochar),
                    r32(obj + O.oshape))
                -- multipart lane RAM: sag(32) size(32) ctrl(16) dx(16) dy(16),
                -- zero longword terminated (ani2, MKUTIL.ASM)
                if img ~= 0 then
                    local lane, p = 0, img
                    while lane < 12 do
                        local lsag = r32(p)
                        if lsag == 0 then break end
                        local llabel = sag_label[lsag] or sag_label[lsag & 0x00ffffff] or "?"
                        log("      lane%d %-16s sag=0x%08x size=%dx%d ctrl=0x%04x d=(%d,%d)",
                            lane, llabel, lsag, r16(p + 0x00 + 0x20), r16(p + 0x30),
                            r16(p + 0x40), s16(r16(p + 0x50)), s16(r16(p + 0x60)))
                        p = p + 0x70
                        lane = lane + 1
                    end
                end
                obj = r32(obj + O.next)
                guard = guard + 1
            end
        end
    end
end

local function finish(ok, reason)
    if finished then return end
    finished = true
    log("%s reason=%s", ok and "DONE" or "FAIL", reason)
    if logfh then logfh:flush() end
    manager.machine:exit()
end

local function pressed(name)
    if charsel_frame == 0 then
        if name == "Coin 1" or name == "Coin 2" then
            return frame >= 220 and frame < 6000 and (frame % 80) < 20
        end
        if name == "2 Players Start" then
            return frame >= 260 and frame < 6000 and (frame % 80) >= 30 and (frame % 80) < 55
        end
    end
    if charsel_frame > 0 and fighting_frame == 0 then
        if name == "P1 High Punch" and p1_confirm_start > 0 then
            return frame >= p1_confirm_start and frame < p1_confirm_start + 40
        end
        if name == "P2 High Punch" and p1_confirm_start > 0 then
            return frame >= p1_confirm_start + 80 and frame < p1_confirm_start + 120
        end
    end
    return false
end

emu.register_frame(function()
    frame = frame + 1
    if frame == 1 then
        cpu = manager.machine.devices[":maincpu"]
        space = cpu.spaces["program"]
        if not cache_fields() then finish(false, "input_missing"); return end
        log("victory objdump probe; dumps at rel %s", table.concat(DUMPS, ","))
    end
    if not space or finished then return end

    local gs = r16(A.gstate)
    if gs ~= last_gstate then
        if gs == GS_PSEL and charsel_frame == 0 then charsel_frame = frame end
        if gs == GS_FIGHTING and last_gstate ~= GS_FIGHTING and fighting_frame == 0 then
            fighting_frame = frame
            log("fight_start frame=%d", frame)
        end
        last_gstate = gs
    end

    if fighting_frame == 0 then
        w16(A.p1_char, FT_RAIDEN)
        w16(A.p2_char, FT_JAX)
        w16(A.curback, STAGE_ID)
        if A.p1_state ~= 0 then w16(A.p1_state, 1) end
        if A.p2_state ~= 0 then w16(A.p2_state, 1) end
        if charsel_frame > 0 and p1_confirm_start == 0 and frame > charsel_frame + 90
            and r16(A.p1_char) == FT_RAIDEN and r16(A.p2_char) == FT_JAX then
            p1_confirm_start = frame + 25
        end
    end

    if fighting_frame > 0 and killed_frame == 0 and frame > fighting_frame + 150 then
        w16(A.p2_bar, 0)
        killed_frame = frame
        log("killed_p2 frame=%d", frame)
    end

    if killed_frame > 0 and win_frame == 0 then
        local ws = r16(A.winner_status)
        if ws == 1 or ws == 2 then
            win_frame = frame
            log("winner_declared frame=%d", frame)
        end
    end

    if win_frame > 0 then
        local rel = frame - win_frame
        for _, d in ipairs(DUMPS) do
            if rel == d then
                dump_objects("rel" .. rel)
                snap("vic_" .. string.format("%03d", rel))
            end
        end

        -- Which pixels does Raiden's object actually draw?  Blank his multipart
        -- lane list for a frame (a zero SAG is the end-of-pieces marker, so the
        -- draw walks nothing) and snapshot again.  Everything that disappears
        -- between the two shots is his; everything that stays is scenery.
        local raiden = r32(A.p1_obj)
        if raiden ~= 0 then
            local img = r32(raiden + O.oimg)
            if rel == 150 then
                snap("A_normal")
            elseif rel == 151 and img ~= 0 then
                blanked_sag = r32(img)
                space:write_u32(img, 0)
                log("blanked raiden lane0 sag=0x%08x at rel=%d", blanked_sag, rel)
            elseif rel == 152 then
                snap("B_blanked")
            elseif rel == 153 and blanked_sag and img ~= 0 then
                space:write_u32(img, blanked_sag)
                log("restored raiden lane0 sag at rel=%d", rel)
            end
        end

        if rel > LAST_DUMP + 5 then finish(true, "dumps_complete"); return end
    end

    if frame > 6000 and win_frame == 0 then finish(false, "never_reached_victory"); return end

    for name, field in pairs(fields) do
        field:set_value(pressed(name) and 1 or 0)
    end
end)
